import { AlertTriangle, ArrowRight, Coins, ExternalLink, Hammer, ShieldCheck } from "lucide-react";
import { useState } from "react";
import { Link, useParams } from "react-router-dom";
import { PageTitle } from "../App";
import { rfEquipmentAdvisor } from "../content/toolboxData";

export function AdvisorPage() {
  const { slug = "rf-chieftain" } = useParams();
  const guide = slug === "rf-chieftain" ? rfEquipmentAdvisor : rfEquipmentAdvisor;
  const [selected, setSelected] = useState(guide.targets[0]!.id);
  const target = guide.targets.find((entry) => entry.id === selected) ?? guide.targets[0]!;

  return (
    <div className="page advisor-page">
      <PageTitle
        eyebrow="CURATED EQUIPMENT ADVISOR · 3.29"
        title={guide.title.zhTW}
        description={`${guide.summary.zhTW} (${guide.title.en})`}
      >
        <Link className="button secondary" to="/compare">開啟 PoB 比較 <ArrowRight size={16} /></Link>
      </PageTitle>

      <div className="advisor-tabs" role="tablist">
        {guide.targets.map((entry) => (
          <button key={entry.id} className={entry.id === target.id ? "active" : ""} onClick={() => setSelected(entry.id)}>
            <span>{entry.slot.zhTW}</span><small>{entry.slot.en}</small>
          </button>
        ))}
      </div>

      <section className="advisor-hero panel">
        <div>
          <span className="eyebrow">{target.baseType.en}</span>
          <h2>{target.itemName.zhTW}</h2>
          <p>{target.itemName.en} · {target.baseType.zhTW}</p>
        </div>
        <div className="advisor-cost">
          <Coins size={21} />
          <small>規劃成本 / Planning range</small>
          <strong>{target.estimatedCostChaos[0]}–{target.estimatedCostChaos[1]}c</strong>
        </div>
      </section>

      <div className="advisor-layout">
        <section className="panel">
          <div className="panel-title"><ShieldCheck size={19} /><div><h3>目標詞綴</h3><small>DESIRED MODIFIERS</small></div></div>
          <div className="desired-mods">
            {target.desiredMods.map((modifier) => (
              <div key={modifier.label.en}>
                <span className={`priority ${modifier.priority}`}>{modifier.priority}</span>
                <p><strong>{modifier.label.zhTW}</strong><small>{modifier.label.en}</small></p>
              </div>
            ))}
          </div>
        </section>
        <section className="panel">
          <div className="panel-title"><Hammer size={19} /><div><h3>製作路線</h3><small>CRAFTING ROUTE</small></div></div>
          <ol className="advisor-steps">
            {target.steps.map((step, index) => (
              <li key={step.title.en}>
                <span>{String(index + 1).padStart(2, "0")}</span>
                <div>
                  <div className="step-heading"><strong>{step.title.zhTW}</strong><em className={`risk ${step.risk}`}>{step.risk}</em></div>
                  <small>{step.title.en}</small>
                  <p>{step.detail.zhTW}</p>
                  <b>{step.cost}</b>
                </div>
              </li>
            ))}
          </ol>
        </section>
      </div>

      <section className="advisor-footer-grid">
        <article className="panel">
          <h3>可接受替代品</h3>
          <ul>{target.alternatives.map((value) => <li key={value.en}>{value.zhTW}<small>{value.en}</small></li>)}</ul>
        </article>
        <article className="panel warning-panel">
          <h3><AlertTriangle size={17} /> 判讀限制</h3>
          <ul>{target.warnings.map((value) => <li key={value.en}>{value.zhTW}<small>{value.en}</small></li>)}</ul>
        </article>
      </section>

      <div className="advisor-actions">
        <Link className="button secondary" to={`/guide/rf-chieftain?stage=${target.stageId}`}>查看對應攻略階段</Link>
        <Link className="button secondary" to="/craft">先在模擬器試做</Link>
        <a className="button primary" href={target.tradeUrl} target="_blank" rel="noreferrer">開啟台服官方市集 <ExternalLink size={15} /></a>
      </div>
    </div>
  );
}
